        sta CIADDRA
        lda #$00
        sta CIADDRB
        lda #$fe
        sta CIAPRA
        lda CIAPRB                      ; Acts only when the key row changes.
        cmp last_key_row
        beq title_keys_fire
        sta last_key_row
        cmp #$ef
        beq title_key_f1
        cmp #$df
        beq title_key_f3
        cmp #$bf
        beq title_key_f5
        cmp #$f7
        beq title_key_f7
title_keys_fire
