        bne title_keys_fire
        lda #$80
        rts
title_key_f3
        lda in_game
        bne title_f3_done
        inc two_player_mode
        lda two_player_mode
        cmp #$02
        bne title_f3_show
        lda #$00
        sta two_player_mode
title_f3_show
        jsr show_mode_text
        jsr high_score_show
title_f3_done
        lda #$00
        rts
title_key_f7
        lda #$00                        ; F7 does nothing.
        rts
title_key_f5
        jmp title_main_loop             ; F5 works also during a game; the stack is not reset.
; Title loop: one player, then the high score, the mode text and the demo again and again. A start key or fire starts the game of two_player_mode.
title_main_loop
        lda #$00
        sta two_player_mode
title_demo_loop
        jsr high_score_show
        jsr show_mode_text
        lda #$00
        sta in_game
        ldx #$09
        jsr score_clear
        ldx #$19
        jsr score_clear
        jsr demo_play
        bpl title_demo_loop             ; N clear: the demo ended without a start key.
        lda two_player_mode
        beq title_start_1p
title_test_2p
        cmp #$01
        beq title_start_2p
title_bad_mode
; not executed $19cc-$19cc
        rts                             ; No mode 2 or more exists.
title_start_1p
        jsr game_one_player
title_1p_again
        lda CIAPRA                      ; Fire held at the end starts a new one-player game.
        and #$10
        beq title_start_1p
        jmp title_demo_loop
title_start_2p
        jsr game_two_players
        bmi title_start_2p
        jmp title_demo_loop
